# ---- S1027v Vigil of SS. Simon and Jude, pp. 598-599 (pdf 338)
P('S1027v','r0',[0,1,2,3,4,6,7],'M39 p. 598 (pdf 338)',why='as printed: "Angelis"; ": Nos infírmi"; ": Vos nóbiles"; ": Maledícimur"; ": Persecutiónem"; ": Blasphemámur"; ": Tamquam"')
_cur=FX[-1]['new']
assert _cur.endswith('caríssimos móneo.')
FX[-1]['new']=_cur[:-1]+': In Christo Jesu Dómino nostro.'; FX[-1]['why']+='; and the Missal\'s ending ": In Christo Jesu Dómino nostro" was missing'
EN('S1027v',0,[('Brethren: I think that God hath set forth us apostles, the last, as it were men appointed to death: we are made','Brethren: We are made'),('as my dearest children.','as my dearest children, in Christ Jesus our Lord.')],'M39 p. 598 (pdf 338)','the Latin begins at v. 9b "Spectáculum facti sumus" (the English had v. 9a "I think that God hath set forth us apostles ..."), and ends with the Missal\'s "In Christo Jesu Dómino nostro"')
P('S1027v','r1',[0,1,2,3,4,5],'M39 pp. 598-599 (pdf 338)',why='as printed: "vitis vera : et Pater"; "Manéte in me : et ego"; ": Qui manet"; "multum : quia"; "mánserit : mittétur"; "mánserint : quodcúmque"')
